const payload = $json.body ?? $json;
if (payload.end_of_turn !== true) return [];
const text = [payload.utterance, payload.transcript, payload.new_text].find((value) => typeof value === 'string' && value.trim())?.trim();
const botId = typeof payload.bot_id === 'string' ? payload.bot_id.trim() : typeof payload.bot_id === 'number' && Number.isFinite(payload.bot_id) ? String(payload.bot_id) : '';
if (!botId || !text) return [];
const speaker = [payload.speakerName, payload.speaker].find((value) => typeof value === 'string' && value.trim())?.trim() ?? 'Speaker';
return [{ json: { bot_id: botId, speaker, text, timestamp: payload.timestamp } }];

const source = $('Keep final speaker turns').first().json;
const original = typeof source.text === 'string' ? source.text.trim() : '';
if (!original) throw new Error('Live turn has no source speech.');
const generated = (Array.isArray($json.output) ? $json.output : []).flatMap(item => Array.isArray(item?.content) ? item.content : []).filter(part => part?.type === 'output_text' && typeof part.text === 'string').map(part => part.text.trim()).filter(Boolean).join('\n');
if (!generated || /^(null|undefined)$/i.test(generated)) throw new Error('AI returned no summary text. Check the model response before continuing.');
const groupReference = /\b(?:we|our|us)\b/i;
const keepOriginal = original.split(/\s+/u).length <= 6 || (groupReference.test(original) && !groupReference.test(generated));
const summary = keepOriginal ? original : generated;
if (summary.split(/\s+/u).length > 65) throw new Error('Live summary is too long. Review the model response before continuing.');
return [{ json: { bot_id: source.bot_id, speaker: source.speaker, summary, source_text: original, timestamp: source.timestamp } }];
